#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_INCOMING_WAN_DMZ FW_INCOMING_DMZ_LAN FW_OUTGOING_DMZWAN FW_OUTGOING_LANDMZ FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_admins && fail 'an IP group named fws_admins exists; nothing was written'
named FW_GROUP_IP fws_dmz-web && fail 'an IP group named fws_dmz-web exists; nothing was written'
named FW_GROUP_PORT fws_tcp-80_443_8000-8080 && fail 'a port group named fws_tcp-80_443_8000-8080 exists; nothing was written'
named FW_GROUP_IP fws_web_for_everyone_dst && fail 'an IP group named fws_web_for_everyone_dst exists; nothing was written'
named FW_GROUP_IP fws_web_for_everyone-2_src && fail 'an IP group named fws_web_for_everyone-2_src exists; nothing was written'
named FW_GROUP_IP fws_rest_of_the_DMZ_dst && fail 'an IP group named fws_rest_of_the_DMZ_dst exists; nothing was written'
named FW_GROUP_PORT fws_tcp-0-21_23-65535 && fail 'a port group named fws_tcp-0-21_23-65535 exists; nothing was written'
named FW_GROUP_PORT fws_tcp-80_443 && fail 'a port group named fws_tcp-80_443 exists; nothing was written'
named FW_GROUP_IP fws_mirrors && fail 'an IP group named fws_mirrors exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_admins --set .COMMENT 'FWShift: admins'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.50-192.168.10.59
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dmz-web --set .COMMENT 'FWShift: dmz-web'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.10/31
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_web_for_everyone_dst --set .COMMENT 'FWShift: dmz-web, 203.0.113.3'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.10/31
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.3
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_web_for_everyone-2_src --set .COMMENT 'FWShift: not admins'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-192.168.10.49
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.60-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_rest_of_the_DMZ_dst --set .COMMENT 'FWShift: not 172.16.20.0/25'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-172.16.19.255
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.128-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_mirrors --set .COMMENT 'FWShift: mirrors'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.80
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-80_443_8000-8080 --set .COMMENT 'FWShift: tcp-80,443,8000-8080'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8000-8080
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-0-21_23-65535 --set .COMMENT 'FWShift: tcp-0-21,23-65535'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 0-21
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 23-65535
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-80_443 --set .COMMENT 'FWShift: tcp-80,443'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.3 --set .IN_PORT 8443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'defconf: drop all from WAN not DSTNATed (allows publish web): what RouterOS rule forward-15 does not block: connections'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.4 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'defconf: drop all from WAN not DSTNATed (allows publish mail): what RouterOS rule forward-15 does not block: connections'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'defconf: drop all from WAN not DSTNATed'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF all --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'LAN to the package mirrors'
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_mirrors
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_tcp-80_443
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'ssh from the admins'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.FROM_IP" fws_admins
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_dmz-web
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'web for everyone'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.FROM_IP" fws_admins
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_web_for_everyone_dst
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_tcp-80_443_8000-8080
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'web for everyone-2: RouterOS /ip firewall filter rule forward-6.to-dmz-3'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.FROM_IP" fws_web_for_everyone-2_src
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_web_for_everyone_dst
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_tcp-80_443_8000-8080
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.3 --set .IN_PORT 8443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'defconf: drop all from WAN not DSTNATed (allows publish web): what RouterOS rule forward-15 does not block: connections'
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.4 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'defconf: drop all from WAN not DSTNATed (allows publish mail): what RouterOS rule forward-15 does not block: connections'
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'defconf: drop all from WAN not DSTNATed'
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_INCOMING_DMZ_LAN
N=$(rows FW_INCOMING_DMZ_LAN)
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING_DMZWAN
N=$(rows FW_OUTGOING_DMZWAN)
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'ssh from the admins'
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_admins
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_dmz-web
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'web for everyone'
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_admins
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_web_for_everyone_dst
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_tcp-80_443_8000-8080
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'web for everyone-2: RouterOS /ip firewall filter rule forward-6.to-dmz-3'
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_web_for_everyone-2_src
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_web_for_everyone_dst
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_tcp-80_443_8000-8080
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'LAN to the package mirrors'
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_mirrors
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_tcp-80_443
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 0.0.0.0/0 --set .COMMENT 'defconf: masquerade'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
